use bevy::app::AppExit;
use bevy::prelude::*;
use std::fs;
use crate::combat::{CombatState,Equipment,PlayerStats,Score,HighScores,TreasureState};
use crate::player::Player;
use crate::world::Level;

#[derive(Component)] struct StatusText;
#[derive(Component)] struct PlayerCardText;
#[derive(Component)] struct MonsterCardText;
#[derive(Component)] struct EndPanel;
#[derive(Component)] struct EndText;
#[derive(Component)] struct NamePanel;
#[derive(Component)] struct NameText;
#[derive(Component)] struct GameText;
#[derive(Resource,Default)] pub struct RestartRequest(pub bool);
#[derive(Resource,Default)] pub struct PlayerProfile { pub name:String, pub confirmed:bool }

pub struct UiPlugin;
impl Plugin for UiPlugin { fn build(&self,app:&mut App){app.init_resource::<RestartRequest>().init_resource::<PlayerProfile>().add_systems(Startup,setup_ui).add_systems(Update,(name_input,update_ui,end_controls));} }

fn font_handle(fonts:&mut Assets<Font>)->Handle<Font>{
    for path in ["/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf","/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf"] {
        if let Ok(bytes)=fs::read(path) { return fonts.add(Font::from_bytes(bytes)); }
    }
    Handle::default()
}
fn tf(font:&Handle<Font>,size:f32)->TextFont{TextFont{font:FontSource::Handle(font.clone()),font_size:FontSize::Px(size),..default()}}
fn card_node(left:Option<f32>,right:Option<f32>)->Node{Node{position_type:PositionType::Absolute,left:left.map(px).unwrap_or(Val::Auto),right:right.map(px).unwrap_or(Val::Auto),top:px(24),width:px(285),min_height:px(360),padding:UiRect::all(px(18)),border:UiRect::all(px(3)),flex_direction:FlexDirection::Column,row_gap:px(8),..default()}}
fn setup_ui(mut commands:Commands,mut fonts:ResMut<Assets<Font>>){let f=font_handle(&mut fonts);
 commands.spawn((card_node(Some(24.),None),BackgroundColor(Color::srgba(0.035,0.055,0.045,0.94)),BorderColor::all(Color::srgb(0.38,0.72,0.46)),children![(Text::new("PERSONNAGE"),tf(&f,25.),TextColor(Color::WHITE),GameText),(Text::new(""),tf(&f,18.),TextColor(Color::srgb(0.88,0.95,0.88)),PlayerCardText,GameText)]));
 commands.spawn((card_node(None,Some(24.)),BackgroundColor(Color::srgba(0.065,0.035,0.035,0.94)),BorderColor::all(Color::srgb(0.75,0.32,0.28)),children![(Text::new("MONSTRE"),tf(&f,25.),TextColor(Color::WHITE),GameText),(Text::new(""),tf(&f,18.),TextColor(Color::srgb(0.96,0.88,0.86)),MonsterCardText,GameText)]));
 commands.spawn((Node{position_type:PositionType::Absolute,left:px(320),right:px(320),bottom:px(18),padding:UiRect::axes(px(14),px(9)),justify_content:JustifyContent::Center,..default()},BackgroundColor(Color::srgba(0.02,0.025,0.02,0.90)),children![(Text::new(""),tf(&f,17.),TextColor(Color::srgb(0.72,0.92,0.72)),StatusText,GameText)]));
 commands.spawn((Node{position_type:PositionType::Absolute,left:px(330),right:px(330),top:px(150),bottom:px(150),padding:UiRect::all(px(25)),align_items:AlignItems::Center,justify_content:JustifyContent::Center,display:Display::None,..default()},BackgroundColor(Color::srgba(0.02,0.02,0.02,0.97)),children![(Text::new(""),tf(&f,30.),TextColor(Color::WHITE),EndText)],EndPanel));
 commands.spawn((Node{position_type:PositionType::Absolute,left:px(360),right:px(360),top:px(190),bottom:px(190),padding:UiRect::all(px(30)),align_items:AlignItems::Center,justify_content:JustifyContent::Center,..default()},BackgroundColor(Color::srgba(0.01,0.01,0.015,0.985)),children![(Text::new("ENTREZ VOTRE PRÉNOM\n\n_\n\n[ENTRÉE] Valider   [RETOUR] Effacer"),tf(&f,28.),TextColor(Color::WHITE),NameText)],NamePanel));
}
fn key_char(k:&ButtonInput<KeyCode>)->Option<char>{let keys=[(KeyCode::KeyA,'A'),(KeyCode::KeyB,'B'),(KeyCode::KeyC,'C'),(KeyCode::KeyD,'D'),(KeyCode::KeyE,'E'),(KeyCode::KeyF,'F'),(KeyCode::KeyG,'G'),(KeyCode::KeyH,'H'),(KeyCode::KeyI,'I'),(KeyCode::KeyJ,'J'),(KeyCode::KeyK,'K'),(KeyCode::KeyL,'L'),(KeyCode::KeyM,'M'),(KeyCode::KeyN,'N'),(KeyCode::KeyO,'O'),(KeyCode::KeyP,'P'),(KeyCode::KeyQ,'Q'),(KeyCode::KeyR,'R'),(KeyCode::KeyS,'S'),(KeyCode::KeyT,'T'),(KeyCode::KeyU,'U'),(KeyCode::KeyV,'V'),(KeyCode::KeyW,'W'),(KeyCode::KeyX,'X'),(KeyCode::KeyY,'Y'),(KeyCode::KeyZ,'Z')];for (key,c) in keys{if k.just_pressed(key){return Some(c)}}None}
fn name_input(k:Res<ButtonInput<KeyCode>>,mut p:ResMut<PlayerProfile>,mut q:Query<&mut Text,With<NameText>>){if p.confirmed{return;}if let Some(c)=key_char(&k){if p.name.len()<12{p.name.push(c);}}if k.just_pressed(KeyCode::Backspace){p.name.pop();}if k.just_pressed(KeyCode::Enter)&&!p.name.is_empty(){p.confirmed=true;}if let Ok(mut t)=q.single_mut(){*t=Text::new(format!("ENTREZ VOTRE PRÉNOM\n\n{}{}\n\n[ENTRÉE] Valider   [RETOUR] Effacer",p.name,if p.name.len()<12{"_"}else{""}));}}
fn update_ui(profile:Res<PlayerProfile>,combat:Res<CombatState>,level:Res<Level>,equipment:Res<Equipment>,score:Res<Score>,_highs:Res<HighScores>,treasure:Res<TreasureState>,q:Query<&PlayerStats,With<Player>>,mut np:Query<&mut Node,(With<NamePanel>,Without<EndPanel>)>,mut pc:Query<&mut Text,(With<PlayerCardText>,Without<MonsterCardText>,Without<StatusText>,Without<EndText>,Without<NameText>)>,mut mc:Query<&mut Text,(With<MonsterCardText>,Without<PlayerCardText>,Without<StatusText>,Without<EndText>,Without<NameText>)>,mut status:Query<&mut Text,(With<StatusText>,Without<PlayerCardText>,Without<MonsterCardText>,Without<EndText>,Without<NameText>)>,mut ep:Query<&mut Node,(With<EndPanel>,Without<NamePanel>)>,mut et:Query<&mut Text,(With<EndText>,Without<PlayerCardText>,Without<MonsterCardText>,Without<StatusText>,Without<NameText>)>){if let Ok(mut n)=np.single_mut(){n.display=if profile.confirmed{Display::None}else{Display::Flex};}let Ok(stats)=q.single()else{return;};if let Ok(mut t)=pc.single_mut(){let w=equipment.weapon.map(|w|format!("{} ({})",w.name(),w.damage_label())).unwrap_or_else(||"À CHOISIR".into());*t=Text::new(format!("{}\n\nPV : {}/{}\nFOR : {}   INT : {}\nCON : {}   WIS : {}\nDEX : {}   CHA : {}\n\nArme : {}\n\nHIGHSCORE PERMANENT\nMonstres tués : {}\nOr : {} pièces",if profile.name.is_empty(){"JOUEUR"}else{&profile.name},combat.player_hp,combat.player_max_hp,stats.for_,stats.int_,stats.con,stats.wis,stats.dex,stats.cha,w,score.monsters_killed,score.gold));}if let Ok(mut t)=mc.single_mut(){if let Some(m)=combat.monster{let(hp,def,atk,dmg)=m.stats();*t=Text::new(format!("{}\n\nPV : {}/{}\nDéfense : {}\nAttaque : {}\nDégâts : D{}\n\n{}{}",m.name(),combat.monster_hp,hp,def,atk,dmg,combat.last_message,if combat.active{"\n\n[ESPACE] Attaquer"}else{""}));}else{*t=Text::new("Aucun adversaire\n\nExplorez la carte. Les monstres restent cachés ; les coffres apparaissent lorsqu'ils sont découverts.");}}let ended=profile.confirmed&&(level.finished||combat.game_over);if let Ok(mut p)=ep.single_mut(){p.display=if ended{Display::Flex}else{Display::None};}if ended{if let Ok(mut t)=et.single_mut(){let reason=if combat.game_over{"Vous avez été vaincu."}else{"Vous avez atteint la sortie."};*t=Text::new(format!("FIN - {}\n\n{}\n\nMonstres tués : {}\nOr total : {}\n\n[ENTRÉE] Nouvelle partie\n[ÉCHAP] Quitter",profile.name,reason,score.monsters_killed,score.gold));}}if let Ok(mut s)=status.single_mut(){*s=Text::new(if !profile.confirmed{"Saisissez votre prénom pour commencer.".into()}else if equipment.weapon.is_none(){"CHOISISSEZ VOTRE ARME : [1] Épée 1D8   [2] Marteau 2D3   [3] Épée+bouclier 1D6 +2 DEF   [4] Hache 1D10".into()}else if combat.active{"COMBAT - ESPACE pour attaquer".into()}else if treasure.pending{treasure.message.clone()}else if !treasure.message.is_empty(){treasure.message.clone()}else if ended{"Partie terminée.".into()}else if combat.victory{"Victoire ! Continuez l'exploration.".into()}else{"Déplacement : ZQSD / WASD / Flèches".into()});}}
fn end_controls(k:Res<ButtonInput<KeyCode>>,profile:Res<PlayerProfile>,level:Res<Level>,combat:Res<CombatState>,mut restart:ResMut<RestartRequest>,mut exit:MessageWriter<AppExit>){if !profile.confirmed||!(level.finished||combat.game_over){return;}if k.just_pressed(KeyCode::Enter){restart.0=true;}if k.just_pressed(KeyCode::Escape){exit.write(AppExit::Success);}}
